import java.util.*;import java.nio.file.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes{
 static void guard(MethodNode m,String name){InsnList l=new InsnList();l.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/isotacz/NativeActions",name,"()Z",false));LabelNode normal=new LabelNode();l.add(new JumpInsnNode(IFEQ,normal));if(m.desc.endsWith(")Z")){l.add(new InsnNode(ICONST_0));l.add(new InsnNode(IRETURN));}else l.add(new InsnNode(RETURN));l.add(normal);l.add(new FrameNode(F_SAME,0,null,0,null));if(m.name.equals("tickXIVHEAD")){AbstractInsnNode anchor=null;for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals("dev/zomboid/isotacz/Bridge")&&call.name.equals("session")){anchor=i;break;}if(anchor==null)throw new IllegalStateException("Missing session hook");m.instructions.insert(anchor,l);}else m.instructions.insert(l);}
 public static void main(String[] a)throws Exception{Map<String,byte[]> data=new TreeMap<>();int guards=0;try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[] bytes=z.getInputStream(e).readAllBytes();if(e.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(bytes).accept(c,0);boolean changed=false;for(MethodNode m:c.methods){String action=null;if(c.name.equals("dev/zomboid/isotacz/Bridge")&&Set.of("mouse","aim","sprintOverride").contains(m.name))action=m.name.equals("mouse")?"nativeInput":"riding";if(c.name.endsWith("/mixin/KeyboardInputMixin")&&m.name.equals("movementXIV"))action="riding";if(c.name.endsWith("/mixin/KeyBindingMixin")&&Set.of("isPressedMouse","isPressedXIV","wasPressedXIV").contains(m.name))action="nativeInput";if(c.name.endsWith("/mixin/MinecraftClientMixin")&&m.name.equals("doAttackXIV"))action="riding";if(c.name.endsWith("/mixin/MinecraftClientMixin")&&m.name.equals("lookAt")&&m.desc.endsWith("Z)V"))action="riding";if(c.name.endsWith("/mixin/MinecraftClientMixin")&&m.visibleAnnotations!=null&&m.visibleAnnotations.stream().anyMatch(n->n.desc.endsWith("/Inject;"))&&m.name.equals("tickXIVHEAD"))action="nativeInput";if(action!=null){guard(m,action);guards++;changed=true;}}if(changed){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);bytes=w.toByteArray();}}data.put(e.getName(),bytes);}}
 if(guards<9)throw new IllegalStateException("Missing guards: "+guards);
 try(var paths=Files.walk(Path.of(a[2]))){for(Path p:paths.filter(Files::isRegularFile).toList())data.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}
 data.put("META-INF/neoforge.mods.toml",new String(data.get("META-INF/neoforge.mods.toml"),java.nio.charset.StandardCharsets.UTF_8).replace("3.6.2+zomboid.18","3.6.2+zomboid.19").getBytes(java.nio.charset.StandardCharsets.UTF_8));
 for(var entry:data.entrySet())if(entry.getKey().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(entry.getValue()).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<>(new BasicVerifier()).analyze(c.name,m);}
 try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:data.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}System.out.println("Native-action guards: "+guards);
 }
}
